import XCTest
@testable import AppCore

final class ClipboardPrivacyTests: XCTestCase {

    // MARK: - Sensitive pasteboard types

    func testSensitiveMarkerTypesAreSensitive() {
        for marker in ["org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
                       "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword"] {
            XCTAssertTrue(ClipboardMonitor.isSensitive(typeIdentifiers: ["public.utf8-plain-text", marker]),
                          "\(marker) should mark the copy sensitive")
        }
    }

    func testOrdinaryTypesAreNotSensitive() {
        XCTAssertFalse(ClipboardMonitor.isSensitive(typeIdentifiers: [
            "public.utf8-plain-text", "public.rtf", "public.png", "public.html", "public.file-url"
        ]))
        XCTAssertFalse(ClipboardMonitor.isSensitive(typeIdentifiers: []))
    }

    // MARK: - SHA-256

    func testContentHashMatchesKnownVectors() {
        // FIPS 180-2 test vector.
        XCTAssertEqual(ContentHash.sha256Hex("abc"),
                       "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad")
        XCTAssertEqual(ContentHash.sha256Hex(""),
                       "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855")
        XCTAssertEqual(ContentHash.sha256Hex(Data("abc".utf8)), ContentHash.sha256Hex("abc"))
    }

    // MARK: - HTML sanitiser

    private func assertNoRemote(_ html: String, file: StaticString = #filePath, line: UInt = #line) {
        let out = HTMLSanitizer.sanitize(html)
        for needle in ["evil.example", "http://", "https://", "//cdn"] {
            XCTAssertFalse(out.lowercased().contains(needle),
                           "\(needle) survived in: \(out)", file: file, line: line)
        }
    }

    func testStripsRemoteImagesAndSrcset() {
        assertNoRemote(#"<p>Hi <img src="http://evil.example/a.png"> there</p>"#)
        assertNoRemote(#"<img srcset="https://evil.example/a.png 1x, https://evil.example/b.png 2x">"#)
        assertNoRemote(#"<picture><source srcset="https://evil.example/a.webp"><img src="https://evil.example/a.png"></picture>"#)
    }

    func testStripsLinkScriptIframeObject() {
        assertNoRemote(#"<link rel="stylesheet" href="https://evil.example/s.css"><p>x</p>"#)
        assertNoRemote(#"<script src="https://evil.example/s.js"></script><p>x</p>"#)
        assertNoRemote(#"<iframe src="https://evil.example/frame"></iframe>"#)
        assertNoRemote(#"<object data="https://evil.example/o.swf"></object><embed src="https://evil.example/e">"#)
        assertNoRemote(#"<video poster="https://evil.example/p.png" src="https://evil.example/v.mp4"></video>"#)
    }

    func testStripsCSSURLsAndImports() {
        assertNoRemote(#"<div style="background:url(http://evil.example/bg.png)">x</div>"#)
        assertNoRemote(#"<div style='background-image: url("https://evil.example/bg.png")'>x</div>"#)
        assertNoRemote(#"<style>@import url("https://evil.example/s.css"); p { color: red }</style>"#)
        assertNoRemote(#"<style>@import 'https://evil.example/s.css';</style>"#)
        assertNoRemote(#"<style>p { background: \75 rl(https://evil.example/x.png) }</style>"#)
        assertNoRemote(#"<style>p { background: image-set("https://evil.example/x.png" 1x) }</style>"#)
        assertNoRemote(#"<div style="background:u&#114;l(https://evil.example/x.png)">x</div>"#)
    }

    func testStripsBackgroundMetaRefreshAndBase() {
        assertNoRemote(#"<body background="https://evil.example/bg.png"><table background=https://evil.example/t.png><tr><td>x</td></tr></table></body>"#)
        assertNoRemote(#"<meta http-equiv="refresh" content="0; url=https://evil.example/">"#)
        assertNoRemote(#"<base href="https://evil.example/"><img src="a.png">"#)
    }

    func testHandlesUnquotedSingleQuotedAndMixedCase() {
        assertNoRemote(#"<IMG SRC=http://evil.example/a.png>"#)
        assertNoRemote(#"<Img Src='http://evil.example/a.png'>"#)
        assertNoRemote(#"<ImG/src=http://evil.example/a.png>"#)
        assertNoRemote(#"<LINK REL=stylesheet HREF=http://evil.example/s.css>"#)
        assertNoRemote(#"<p STYLE="BACKGROUND:URL(http://evil.example/x.png)">x</p>"#)
        assertNoRemote(#"<img alt="a>b" src="http://evil.example/a.png">"#)
        // An unbalanced quote defeats the tag pattern; the tag must then be
        // escaped to inert text rather than reach the importer as markup.
        let unbalanced = HTMLSanitizer.sanitize(#"<img src=http://evil.example/a'b.png>"#)
        XCTAssertFalse(unbalanced.lowercased().contains("<img"), unbalanced)
    }

    func testKeepsTextFormattingAndAnchors() {
        let html = #"<p>Hello <b>bold</b> and <a href="https://example.org/page">a link</a></p>"#
        let out = HTMLSanitizer.sanitize(html)
        XCTAssertTrue(out.contains("Hello"))
        XCTAssertTrue(out.contains("<b>bold</b>"))
        XCTAssertTrue(out.contains(#"href="https://example.org/page""#), out)
        XCTAssertTrue(out.contains("a link"))
        XCTAssertEqual(HTMLSanitizer.sanitize("plain text, no markup"), "plain text, no markup")
    }

    func testKeepsHarmlessInlineStyle() {
        let out = HTMLSanitizer.sanitize(#"<span style="color: red; font-weight: bold">x</span>"#)
        XCTAssertTrue(out.contains("color: red"), out)
    }
}
